import { useXLSX } from '../src/core/xlsx.js';
import { pdfToText } from './pdf-text.js';
import { mountWorkspace, pickStore } from './workspace-ui.js';
import { mountPrices } from './price-ui.js';
import { mountStorage } from './storage-ui.js';
import { Workspace } from '../src/core/workspace.js';
import { applyPriceBook } from '../src/core/pricebook.js';
import { CSS } from './widget-style.js';
import { renderCategories } from './findings-view.js';
import { groupFindings, detailRows } from '../src/core/findings-table.js';
import { buildReportXlsx, detailSheet, categorySheet } from '../src/core/xlsx-report.js';

const COMPANIES = { hyundai: ['현대건설', '품셈'], gyeryong: ['계룡건설', '단가제'], hanwha: ['한화건설', '단가제'] };
const GRADES = ['특급기술자', '고급기술자', '중급기술자', '초급기술자'];
const GROUPS = [['estimate', '견적서 검토'], ['submission', '사업장 제출용 ↔ 견적서'], ['results', '결과서 검토'], ['resultSet', '결과서 간 비교'], ['compare', '결과서 ↔ 견적서']];
const SEV = { error: '오류', warn: '주의', info: '참고' };
const ORDER = { error: 0, warn: 1, info: 2 };
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// 번들 형태에 따라 import.meta.url 이 없을 수 있어 실패하면 현재 페이지 기준으로 한다
const defaultBase = () => { try { return new URL('./', import.meta.url).href; } catch { return location.href.replace(/[^/]*$/, ''); } };

// ── 외부 라이브러리 지연 로드 (SheetJS / pdf.js)
const loaded = new Map();
function loadScript(src) {
  if (!loaded.has(src)) loaded.set(src, new Promise((ok, no) => { const s = document.createElement('script'); s.src = src; s.onload = ok; s.onerror = () => no(new Error('라이브러리를 불러오지 못했습니다: ' + src)); document.head.appendChild(s); }));
  return loaded.get(src);
}
async function ensureXlsx(base) {
  if (!globalThis.XLSX) await loadScript(base + 'vendor/xlsx.full.min.js');
  useXLSX(globalThis.XLSX);
}
async function ensurePdf(base) {
  if (!globalThis.pdfjsLib) await loadScript(base + 'vendor/pdf.min.js');
  if (!globalThis.pdfjsLib.GlobalWorkerOptions.workerSrc) globalThis.pdfjsLib.GlobalWorkerOptions.workerSrc = base + 'vendor/pdf.worker.min.js';
}
function injectStyle() {
  if (document.getElementById('qr-style')) return;
  const st = document.createElement('style'); st.id = 'qr-style'; st.textContent = CSS; document.head.appendChild(st);
}

// ── 기준 설정 저장/복원 (localStorage 는 막혀 있을 수 있어 항상 try/catch)
const store = {
  get(k) { try { return k ? JSON.parse(localStorage.getItem(k) || 'null') : null; } catch { return null; } },
  set(k, v) { try { if (k) localStorage.setItem(k, JSON.stringify(v)); return true; } catch { return false; } },
  del(k) { try { if (k) localStorage.removeItem(k); } catch { /* 무시 */ } },
};

export function mountReview(el, opts = {}) {
  if (!el) throw new Error('mountReview: 컨테이너 요소가 필요합니다.');
  const o = { company: 'hyundai', companies: Object.keys(COMPANIES), storageKey: 'quotation-review-config-v1', assetBase: defaultBase(), showConfig: true, darkAuto: true, ...opts };
  o.companies = o.companies.filter((c) => COMPANIES[c]);
  if (!o.companies.length) o.companies = Object.keys(COMPANIES);
  if (!o.companies.includes(o.company)) o.company = o.companies[0];
  if (!o.assetBase.endsWith('/')) o.assetBase += '/';
  injectStyle();

  const st = { view: opts.view || (opts.company ? o.company : 'work'), est: null, sub: null, res: [], last: null, busy: false, destroyed: false };
  let cfg = mergeConfig(o.config ?? store.get(o.storageKey) ?? {});

  el.classList.add('qr'); if (o.darkAuto) el.classList.add('qr-auto-dark');
  el.innerHTML = `
    <div class="qr-shell">
    <aside class="qr-side" data-r="tabs" aria-label="메뉴">
      <div class="qr-side-title">${esc(o.title || '검토 도구')}</div>
      <div class="qr-side-h">분기 업무</div>
      <button data-co="work">분기 작업</button>
      <button data-co="price">단가 등록</button>
      <div class="qr-side-h">빠른 검토</div>
      ${o.companies.map((c) => `<button data-co="${c}">${COMPANIES[c][0]}</button>`).join('')}
      <div class="qr-side-h">설정</div>
      ${o.showConfig ? '<button data-co="config">기준 관리</button>' : ''}
      <button data-co="storage">저장 위치</button>
    </aside>
    <main class="qr-main">
    <section data-r="work" hidden><div data-r="work-root"><p class="qr-mute">불러오는 중…</p></div></section>
    <section data-r="price" hidden><div data-r="price-root"><p class="qr-mute">불러오는 중…</p></div></section>
    <section data-r="storage" hidden><div data-r="storage-root"></div></section>
    <section data-r="review">
      <div class="qr-card">
        <h2>1. 파일 올리기</h2>
        <div class="qr-grid">
          <label class="qr-drop" data-r="drop-est"><b>견적서</b><span data-r="hint-est"></span><input type="file" data-r="f-est" accept=".xlsx,.xlsm,.xls"><em data-r="n-est"></em></label>
          <label class="qr-drop" data-r="drop-sub" data-only="hyundai"><b>사업장 제출용 엑셀 <small>(선택)</small></b><span>실시현황·계획서·재료비 — 견적서와 일치하는지 대조</span><input type="file" data-r="f-sub" accept=".xlsx,.xlsm,.xls"><em data-r="n-sub"></em></label>
          <label class="qr-drop" data-r="drop-res"><b>결과서 <small>(선택, 여러 개)</small></b><span>PDF 또는 엑셀</span><input type="file" data-r="f-res" accept=".pdf,.xlsx,.xlsm,.xls" multiple><em data-r="n-res"></em></label>
        </div>
        <div class="qr-row" data-only="hyundai">
          <label>견적 유형 <select data-r="type"><option value="">파일에서 자동 판별</option><option>정기자동</option><option>수시자동</option><option>정기수동</option><option>수시수동</option></select></label>
          <span class="qr-mute">선택한 유형과 파일 내용이 다르면 오류로 표시합니다.</span>
        </div>
        <div class="qr-row"><label>단가 기준 연도 <select data-r="qyear"><option value="auto">등록된 최신 연도</option></select></label><span class="qr-mute">「단가 등록」에서 올린 해당 연도 단가표로 검토합니다 (없으면 기준 관리 값).</span></div>
        <div class="qr-row"><button class="primary" data-r="run" disabled>검토 실행</button><span class="qr-mute" data-r="status" role="status"></span></div>
      </div>
      <div data-r="out" hidden>
        <div class="qr-card">
          <div class="qr-row between"><h2>2. 검토 결과</h2><div class="qr-row" style="margin:0"><label class="qr-chk"><input type="checkbox" data-r="show-info"> 참고 보기</label><button data-r="export">엑셀로 저장</button></div></div>
          <div class="qr-counts" data-r="counts"></div><div class="qr-mute" data-r="stats"></div>
        </div>
        <div data-r="groups"></div>
      </div>
    </section>
    <section data-r="config" hidden>
      <div class="qr-card">
        <h2>기준 관리</h2>
        <p class="qr-mute">정기/수시 견적금액 계수와 인건비 노임단가를 관리합니다. 수시수동은 정기수동과 형태가 같고 이 값만 다릅니다.</p>
        <div class="qr-cfg-grid" data-r="cfg-form"></div>
        <div class="qr-cfg-box" style="margin-top:14px">
          <label>업종 <select data-r="cfg-industry"><option>건설업</option><option>기타</option></select></label>
          <p class="qr-mute" style="margin:4px 0">건설업이면 결과서 갑지에서 "2회 연속 미만/초과" 체크를 오류로 봅니다.</p>
        </div>
        <div class="qr-cfg-box" style="margin-top:14px"><h3>계약 단가표 <small>(계룡·한화 — 견적 단가가 계약 조건과 같은지 검증하는 기준)</small></h3>
          <p class="qr-mute" style="margin:4px 0">계약 단가가 들어 있는 견적 엑셀(‘단가’ 시트)을 올리면 그 단가표를 계약 기준으로 저장합니다. 이후 견적서는 이 기준과 비교합니다.</p>
          ${['gyeryong', 'hanwha'].map((c) => `<div class="qr-row"><b style="width:70px">${COMPANIES[c][0]}</b><span class="qr-mute" data-r="contract-info-${c}"></span><label class="qr-drop" style="min-height:0;padding:4px 12px;border-style:solid"><span style="color:inherit">단가표 올리기</span><input type="file" data-r="contract-${c}" accept=".xlsx,.xlsm,.xls"></label><button data-r="contract-clear-${c}">기준 삭제</button></div>`).join('')}
        </div>
        <div class="qr-cfg-box" style="margin-top:14px"><h3>다성분 묶음 규칙 <small>(같은 분석방법이라도 아무 인자나 한 시료로 묶을 수 있는 것은 아닙니다 — 현대·계룡·한화 공통)</small></h3>
          <p class="qr-mute" style="margin:4px 0">인자 이름은 아래 이름과 <b>정확히 일치</b>할 때만 적용됩니다(공백, (STEL) 표기는 무시).</p>
          <b>단성분 인자</b> <small>(한 줄에 하나 — 다른 인자와 묶이면 오류)</small><textarea data-r="cfg-single" spellcheck="false" style="min-height:64px"></textarea>
          <b>서로끼리만 묶이는 인자</b> <small>(한 줄에 한 묶음, 쉼표로 구분 — 예: 수산화나트륨, 수산화칼륨. 이 묶음 밖의 인자와 묶이면 오류)</small><textarea data-r="cfg-onlywith" spellcheck="false" style="min-height:64px"></textarea>
        </div>
        <details style="margin-top:14px"><summary>유해인자·분석방법 별칭 (JSON)</summary>
          <p class="qr-mute">계룡·한화 견적서의 약칭을 결과서 유해인자명으로, 분석방법명을 단가표 규격명으로 연결합니다.</p>
          <b>유해인자 별칭</b><textarea data-r="cfg-haz" spellcheck="false"></textarea>
          <b>분석방법 별칭</b><textarea data-r="cfg-met" spellcheck="false"></textarea>
        </details>
        <div class="qr-row"><button class="primary" data-r="cfg-save">저장</button><button data-r="cfg-reset">기본값으로</button><button data-r="cfg-export">내보내기</button><label class="qr-drop" style="min-height:0;padding:6px 12px;border-style:solid"><span style="color:inherit">가져오기</span><input type="file" data-r="cfg-import" accept=".json,application/json"></label><span class="qr-msg" data-r="cfg-msg" role="status"></span></div>
      </div>
    </section>
    </main></div>`;
  const $ = (r) => el.querySelector(`[data-r="${r}"]`);
  const $$ = (sel) => el.querySelectorAll(sel);
  const on = (node, ev, fn) => node.addEventListener(ev, fn);

  // ── 탭
  const applyView = () => {
    $$('[data-co]').forEach((b) => b.classList.toggle('on', b.dataset.co === st.view));
    const isCfg = st.view === 'config', isWork = st.view === 'work', isPrice = st.view === 'price', isStore = st.view === 'storage';
    $('review').hidden = isCfg || isWork || isPrice || isStore; $('config').hidden = !isCfg; $('work').hidden = !isWork; $('price').hidden = !isPrice; $('storage').hidden = !isStore;
    if (isCfg) fillConfig();
    if (isWork) startWork();
    if (isPrice) startPrice();
    if (isStore) startStorage();
    if (!isCfg && !isWork && !isPrice && !isStore) fillYears();
    $$('[data-only]').forEach((n) => { n.hidden = n.dataset.only !== st.view; });
    $('hint-est').textContent = st.view === 'hyundai' ? '표준품셈 견적서 (.xlsm) — 정기/수시·자동/수동을 파일에서 자동 판별' : '수수료 산출근거 엑셀 — 현장별 블록 전체';
    if (!isCfg && !isWork && !isPrice && !isStore) { st.last = null; $('out').hidden = true; }
  };
  $$('[data-co]').forEach((b) => on(b, 'click', () => { if (st.busy) return; st.view = b.dataset.co; applyView(); }));

  // ── 저장소·작업 흐름(분기 작업·단가 등록·빠른 검토가 함께 씀) — 처음 필요할 때 만든다
  let core = null, coreP = null, work = null, price = null;
  function ensureCore() {
    coreP ||= (async () => {
      await ensureXlsx(o.assetBase);
      const store = await pickStore(o);
      const ws = new Workspace({ store, user: o.user || '', cfg, pdfToText: async (buf) => { await ensurePdf(o.assetBase); return pdfToText(buf); } });
      try { ws.setUser(localStorage.getItem('qr-user') || o.user || ''); } catch { /* 무시 */ }
      core = { store, ws }; return core;
    })().catch((e) => { coreP = null; throw e; });
    return coreP;
  }
  // 저장소를 못 쓸 때(폴더 접근 허용 필요·서버 연결 실패 등): 안내와 함께 해결 버튼을 보여 준다
  function storeProblem(node, what, e) {
    console.error(e);
    node.innerHTML = `<div class="qr-card"><p class="qr-msg err">${what}을(를) 시작하지 못했습니다: ${esc(e.message || e)}</p><div class="qr-row">${e.code === 'needs-permission' ? '<button class="primary" data-fix="allow">저장 폴더 다시 연결(허용)</button>' : ''}<button data-fix="settings">저장 위치 설정 열기</button></div></div>`;
    node.querySelector('[data-fix="settings"]').onclick = () => { st.view = 'storage'; applyView(); };
    const allow = node.querySelector('[data-fix="allow"]');
    if (allow) allow.onclick = async () => { if (await e.handle.requestPermission({ mode: 'readwrite' }) === 'granted') { await resetCore(); applyView(); } };
  }
  async function startWork() {
    if (work) return;
    try { const { store, ws } = await ensureCore(); if (!work) work = mountWorkspace($('work-root'), { ws, store, onChange: () => { try { o.onWorkChange?.(); } catch (e) { console.error(e); } } }); }
    catch (e) { storeProblem($('work-root'), '분기 작업', e); }
  }
  async function startPrice() {
    if (price) { price.reload().catch(() => {}); return; }
    try { const { ws } = await ensureCore(); if (!price) price = mountPrices($('price-root'), { ws, loadWorkbook }); }
    catch (e) { storeProblem($('price-root'), '단가 등록', e); }
  }
  let storageUi = null;
  function startStorage() {
    if (storageUi) { storageUi.reload(); return; }
    storageUi = mountStorage($('storage-root'), { currentStore: async () => (await ensureCore()).store, onChanged: async () => { await resetCore(); } });
  }
  /** 저장 위치가 바뀌면 저장소·작업 화면을 새로 만든다 (저장 위치 화면은 그대로 둔다) */
  async function resetCore() {
    coreP = null; core = null; work = null; price = null;
    // 이전 화면이 달아 둔 이벤트가 새 저장소와 섞이지 않도록 컨테이너 요소째 새로 만든다
    for (const r of ['work-root', 'price-root']) { const fresh = document.createElement('div'); fresh.dataset.r = r; fresh.innerHTML = '<p class="qr-mute">불러오는 중…</p>'; $(r).replaceWith(fresh); }
    try { await ensureCore(); } catch { /* 저장 위치 화면이 현재 상태를 보여 준다 */ }
    storageUi?.reload();
  }

  async function fillYears() {
    try {
      const book = await (await ensureCore()).ws.getPriceBook();
      const sel = $('qyear'), cur = sel.value;
      sel.innerHTML = '<option value="auto">등록된 최신 연도</option>' + Object.keys(book.years).sort().reverse().map((y) => `<option value="${y}">${y}년</option>`).join('');
      if ([...sel.options].some((x) => x.value === cur)) sel.value = cur;
    } catch { /* 저장소를 못 쓰면 기본 설정으로 검토 */ }
  }

  // ── 파일
  const refresh = () => { $('run').disabled = st.busy || (!st.est && !st.res.length); };
  const names = (fs) => fs.map((f) => f.name).join(', ');
  on($('f-est'), 'change', (e) => { st.est = e.target.files[0] || null; $('n-est').textContent = st.est?.name || ''; refresh(); });
  on($('f-sub'), 'change', (e) => { st.sub = e.target.files[0] || null; $('n-sub').textContent = st.sub?.name || ''; });
  on($('f-res'), 'change', (e) => { st.res = [...e.target.files]; $('n-res').textContent = names(st.res); refresh(); });
  for (const [drop, inp] of [['drop-est', 'f-est'], ['drop-sub', 'f-sub'], ['drop-res', 'f-res']]) {
    const d = $(drop);
    on(d, 'dragover', (ev) => { ev.preventDefault(); d.classList.add('over'); });
    on(d, 'dragleave', () => d.classList.remove('over'));
    on(d, 'drop', (ev) => { ev.preventDefault(); d.classList.remove('over'); const i = $(inp); try { i.files = ev.dataTransfer.files; } catch { return; } i.dispatchEvent(new Event('change')); });
  }

  // ── 실행
  const readBuf = (f) => f.arrayBuffer();
  const isPdf = (f) => /\.pdf$/i.test(f.name);
  const tick = () => new Promise((r) => setTimeout(r));
  async function run() {
    if (st.busy) return;
    st.busy = true; refresh();
    const say = (t) => { if (!st.destroyed) $('status').textContent = t; };
    try {
      say('라이브러리 준비 중…'); await ensureXlsx(o.assetBase);
      say('파일 읽는 중…'); await tick();
      const estimateWb = st.est ? loadWorkbook(await readBuf(st.est), { select: st.view === 'hyundai' ? 'hyundai' : 'all' }) : null;
      const submissionWb = st.sub && st.view === 'hyundai' ? loadWorkbook(await readBuf(st.sub)) : null;
      const results = [];
      for (const f of st.res) {
        say(`결과서 읽는 중… ${f.name}`);
        if (isPdf(f)) { await ensurePdf(o.assetBase); results.push({ name: f.name, text: await pdfToText(await readBuf(f)) }); }
        else results.push({ name: f.name, wb: loadWorkbook(await readBuf(f)) });
      }
      say('검토 중…'); await tick();
      // 등록된 연도별 단가표가 있으면 적용 (노임단가·계수·재료비단가·계약단가)
      let useCfg = cfg, notes = [];
      try {
        const book = await (await ensureCore()).ws.getPriceBook();
        const years = Object.keys(book.years).sort();
        const pick = $('qyear').value === 'auto' ? years[years.length - 1] : $('qyear').value;
        if (pick) ({ cfg: useCfg, notes } = applyPriceBook(cfg, book, st.view, pick));
      } catch (e) { console.warn('단가표를 불러오지 못해 기본 설정으로 검토합니다.', e); }
      st.last = runReview({ company: st.view, type: $('type').value || undefined, estimateWb, submissionWb, results, cfg: useCfg });
      for (const n of notes.reverse()) st.last.estimate.unshift({ severity: 'info', category: '단가표', message: n, where: '' });
      render(); say('');
      try { o.onResult?.(st.last); } catch (e) { console.error('onResult', e); }
    } catch (e) {
      console.error(e); say('오류: ' + (e?.message || e));
    } finally { st.busy = false; refresh(); }
  }
  on($('run'), 'click', run);

  // ── 결과 표시
  function render() {
    const r = st.last; if (!r) return;
    const showInfo = $('show-info').checked;
    const all = GROUPS.flatMap(([k]) => r[k] || []);
    const n = (s) => all.filter((f) => f.severity === s).length;
    $('counts').innerHTML = `<span class="qr-pill error">오류 ${n('error')}</span><span class="qr-pill warn">주의 ${n('warn')}</span><span class="qr-pill info">참고 ${n('info')}</span>${!n('error') && !n('warn') ? '<span class="qr-pill ok">지적 사항 없음</span>' : ''}`;
    $('stats').textContent = r.estimateStats ? Object.entries(r.estimateStats).map(([k, v]) => `${k}: ${v}`).join(' · ') : '';
    $('groups').innerHTML = GROUPS.map(([k, title]) => {
      const raw = r[k] || []; if (!raw.length) return '';
      const list = raw.filter((f) => showInfo || f.severity !== 'info').sort((a, b) => ORDER[a.severity] - ORDER[b.severity]);
      const e = raw.filter((f) => f.severity === 'error').length, w = raw.filter((f) => f.severity === 'warn').length;
      const { body, chips } = renderCategories(list);
      return `<details class="qr-grp" ${e || w ? 'open' : ''}><summary><h3>${title}</h3>${e ? `<span class="qr-badge error">오류 ${e}</span>` : ''}${w ? `<span class="qr-badge warn">주의 ${w}</span>` : ''}${!e && !w ? '<span class="qr-badge info">이상 없음</span>' : ''}</summary><div class="qr-body">${chips}${body || '<div class="qr-mute" style="padding:8px">표시할 항목이 없습니다.</div>'}</div></details>`;
    }).join('');
    $('out').hidden = false;
  }
  on($('show-info'), 'change', render);
  on($('export'), 'click', async () => {
    if (!st.last) return;
    await ensureXlsx(o.assetBase);
    const sum = [], det = [];
    for (const [k, title] of GROUPS) {
      const list = st.last[k] || [];
      for (const c of groupFindings(list)) sum.push([title, c.category, c.error, c.warn, c.info]);
      det.push(...detailRows(list, [title]));
    }
    const bytes = await buildReportXlsx([
      sum.length ? categorySheet('분류별 요약', ['구분', '분류', '오류', '주의', '참고'], sum, { catCol: 1, countCols: { 2: 'error', 3: 'warn', 4: 'info' }, widths: [26, 24, 8, 8, 8] }) : { name: '분류별 요약', rows: [['지적 사항 없음']] },
      det.length ? detailSheet('검토결과(분류별)', ['구분', '분류', '심각도', '내용', '사유·상세', '위치·파일', '곳수'], det, { catCol: 1, sevCol: 2, widths: [26, 20, 8, 60, 60, 38, 6] }) : { name: '검토결과(분류별)', rows: [['지적 사항 없음']] },
    ]);
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' })); a.download = `검토결과_${new Date().toISOString().slice(0, 10)}.xlsx`; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  });

  // ── 기준 관리
  const num = (v) => (v === '' || v == null ? NaN : Number(v));
  function fillConfig() {
    const rates = cfg.companies.hyundai.rates;
    $('cfg-form').innerHTML = ['정기', '수시'].map((p) => `
      <div class="qr-cfg-box" data-per="${p}"><h3>${p} <small>${p === '수시' ? '(수시자동·수시수동 공통)' : '(정기자동·정기수동 공통)'}</small></h3>
        <label>견적금액 계수 <input type="number" step="0.01" min="0" max="1" data-k="factor" value="${rates[p].factor}"></label>
        ${GRADES.map((g) => `<label>${g} 노임단가 <input type="number" step="1" min="0" data-g="${g}" value="${rates[p].wage[g]}"></label>`).join('')}
      </div>`).join('');
    $('cfg-industry').value = cfg.industry === '건설업' ? '건설업' : '기타';
    $('cfg-single').value = (cfg.bundleRules?.single || []).join('\n');
    $('cfg-onlywith').value = (cfg.bundleRules?.onlyWith || []).map((g) => g.join(', ')).join('\n');
    $('cfg-haz').value = JSON.stringify(cfg.hazardAliases, null, 2);
    $('cfg-met').value = JSON.stringify(cfg.methodAliases, null, 2);
    msg(''); contractInfo();
  }
  const contractInfo = () => {
    for (const c of ['gyeryong', 'hanwha']) {
      const k = cfg.companies[c]?.contract; const n = k ? (k.base?.length || 0) : 0, m = k ? Object.keys(k.methods || {}).length : 0;
      $(`contract-info-${c}`).textContent = k && (n || m) ? `등록됨 — 기본관리비 ${n}구간 · 분석수수료 ${m}종` : '등록 안 됨 (견적 파일 안의 단가표 기준으로 검증)';
    }
  };
  for (const c of ['gyeryong', 'hanwha']) {
    on($(`contract-${c}`), 'change', async (e) => {
      const f = e.target.files[0]; e.target.value = ''; if (!f) return;
      try {
        await ensureXlsx(o.assetBase);
        const contract = extractContract(loadWorkbook(await f.arrayBuffer()));
        const next = mergeConfig({}, cfg); next.companies[c].contract = contract;
        if (applyConfig(next)) { contractInfo(); msg(`${COMPANIES[c][0]} 계약 단가표를 저장했습니다.`, 'ok'); }
      } catch (err) { msg('계약 단가표를 읽지 못했습니다: ' + err.message, 'err'); }
    });
    on($(`contract-clear-${c}`), 'click', () => { const next = mergeConfig({}, cfg); delete next.companies[c].contract; if (applyConfig(next)) { contractInfo(); msg('계약 단가표 기준을 삭제했습니다.', 'ok'); } });
  }
  const msg = (t, kind = '') => { const m = $('cfg-msg'); m.textContent = t; m.className = 'qr-msg ' + kind; };
  function readConfigForm() {
    const next = mergeConfig({}, cfg);
    for (const box of $$('[data-per]')) {
      const p = box.dataset.per, r = next.companies.hyundai.rates[p];
      r.factor = num(box.querySelector('[data-k="factor"]').value);
      for (const g of GRADES) r.wage[g] = num(box.querySelector(`[data-g="${g}"]`).value);
    }
    next.industry = $('cfg-industry').value === '건설업' ? '건설업' : '기타';
    const lines = (t) => String(t || '').split(/\n/).map((x) => x.trim()).filter(Boolean);
    next.bundleRules = { single: lines($('cfg-single').value), onlyWith: lines($('cfg-onlywith').value).map((l) => l.split(/[,，]/).map((x) => x.trim()).filter(Boolean)) };
    next.hazardAliases = JSON.parse($('cfg-haz').value || '{}');
    next.methodAliases = JSON.parse($('cfg-met').value || '{}');
    return next;
  }
  function applyConfig(next) {
    const errs = validateConfig(next);
    if (errs.length) { msg(errs[0] + (errs.length > 1 ? ` (외 ${errs.length - 1}건)` : ''), 'err'); return false; }
    cfg = next; core?.ws.setConfig(cfg);
    const saved = store.set(o.storageKey, cfg);
    try { o.onConfigChange?.(JSON.parse(JSON.stringify(cfg))); } catch (e) { console.error('onConfigChange', e); }
    msg(saved || !o.storageKey ? '저장했습니다.' : '적용했지만 브라우저 저장소에는 저장하지 못했습니다.', 'ok');
    return true;
  }
  on($('cfg-save'), 'click', () => {
    let next; try { next = readConfigForm(); } catch (e) { msg('별칭 JSON 형식 오류: ' + e.message, 'err'); return; }
    applyConfig(next);
  });
  on($('cfg-reset'), 'click', () => { store.del(o.storageKey); cfg = mergeConfig({}); core?.ws.setConfig(cfg); try { o.onConfigChange?.(JSON.parse(JSON.stringify(cfg))); } catch (e) { console.error(e); } fillConfig(); msg('기본값으로 되돌렸습니다.', 'ok'); });
  on($('cfg-export'), 'click', () => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([JSON.stringify(cfg, null, 2)], { type: 'application/json' }));
    a.download = 'quotation-review-config.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });
  on($('cfg-import'), 'change', async (e) => {
    const f = e.target.files[0]; e.target.value = ''; if (!f) return;
    try { const next = mergeConfig(JSON.parse(await f.text())); if (applyConfig(next)) fillConfig(); msg('가져와서 저장했습니다.', 'ok'); }
    catch (err) { msg('가져오기 실패: ' + err.message, 'err'); }
  });

  applyView();
  return {
    getConfig: () => JSON.parse(JSON.stringify(cfg)),
    setConfig(next) { cfg = mergeConfig(next ?? {}); core?.ws.setConfig(cfg); if (st.view === 'config') fillConfig(); },
    getWorkspace: () => core?.ws || null,
    getResult: () => st.last,
    destroy() { st.destroyed = true; el.innerHTML = ''; el.classList.remove('qr', 'qr-auto-dark'); },
  };
}
export { DEFAULT_CONFIG, runReview, mergeConfig };
